-- Create "content_nodes" table
CREATE TABLE "content_nodes" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), "kind" character varying NOT NULL DEFAULT 'chapter', "title" character varying NOT NULL, "sequence" bigint NOT NULL, "page_start" bigint NULL, "page_end" bigint NULL, "engine_section_id" character varying NULL, "resolved_at" timestamptz NULL, "origin" character varying NOT NULL DEFAULT 'manual', "locator_json" jsonb NULL, "metadata_json" jsonb NULL, "content_item_id" uuid NOT NULL, "parent_id" uuid NULL, PRIMARY KEY ("id"), CONSTRAINT "content_nodes_content_items_content_item" FOREIGN KEY ("content_item_id") REFERENCES "content_items" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "content_nodes_content_nodes_children" FOREIGN KEY ("parent_id") REFERENCES "content_nodes" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "contentnode_content_item_id_parent_id_sequence" to table: "content_nodes"
CREATE INDEX "contentnode_content_item_id_parent_id_sequence" ON "content_nodes" ("content_item_id", "parent_id", "sequence");
-- Create index "contentnode_engine_section_id" to table: "content_nodes"
CREATE INDEX "contentnode_engine_section_id" ON "content_nodes" ("engine_section_id");
-- Create index "contentnode_resolved_at" to table: "content_nodes"
CREATE INDEX "contentnode_resolved_at" ON "content_nodes" ("resolved_at");
-- Create "curricula" table
CREATE TABLE "curricula" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), "name" character varying NOT NULL, "code" character varying NOT NULL, "board" character varying NULL, "description" text NULL, "origin" character varying NOT NULL DEFAULT 'school', "status" character varying NOT NULL DEFAULT 'draft', "metadata_json" jsonb NULL, "academic_session_id" uuid NOT NULL, "subject_id" uuid NOT NULL, "grade_level_id" uuid NOT NULL, "supersedes_id" uuid NULL, "copied_from_id" uuid NULL, PRIMARY KEY ("id"), CONSTRAINT "curricula_academic_sessions_academic_session" FOREIGN KEY ("academic_session_id") REFERENCES "academic_sessions" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "curricula_curricula_copies" FOREIGN KEY ("copied_from_id") REFERENCES "curricula" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "curricula_curricula_superseded_by" FOREIGN KEY ("supersedes_id") REFERENCES "curricula" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "curricula_grade_levels_grade_level" FOREIGN KEY ("grade_level_id") REFERENCES "grade_levels" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "curricula_subjects_subject" FOREIGN KEY ("subject_id") REFERENCES "subjects" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "curricula_code_key" to table: "curricula"
CREATE UNIQUE INDEX "curricula_code_key" ON "curricula" ("code");
-- Create index "curriculum_academic_session_id_subject_id_grade_level_id" to table: "curricula"
CREATE UNIQUE INDEX "curriculum_academic_session_id_subject_id_grade_level_id" ON "curricula" ("academic_session_id", "subject_id", "grade_level_id") WHERE ((status)::text = 'active'::text);
-- Create index "curriculum_academic_session_id_subject_id_grade_level_id_status" to table: "curricula"
CREATE INDEX "curriculum_academic_session_id_subject_id_grade_level_id_status" ON "curricula" ("academic_session_id", "subject_id", "grade_level_id", "status");
-- Create index "curriculum_copied_from_id" to table: "curricula"
CREATE INDEX "curriculum_copied_from_id" ON "curricula" ("copied_from_id");
-- Create "curriculum_nodes" table
CREATE TABLE "curriculum_nodes" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), "kind" character varying NOT NULL DEFAULT 'topic', "title" character varying NOT NULL, "sequence" bigint NOT NULL, "description" text NULL, "status" character varying NOT NULL DEFAULT 'active', "metadata_json" jsonb NULL, "curriculum_id" uuid NOT NULL, "parent_id" uuid NULL, "copied_from_id" uuid NULL, PRIMARY KEY ("id"), CONSTRAINT "curriculum_nodes_curricula_nodes" FOREIGN KEY ("curriculum_id") REFERENCES "curricula" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "curriculum_nodes_curriculum_nodes_children" FOREIGN KEY ("parent_id") REFERENCES "curriculum_nodes" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "curriculum_nodes_curriculum_nodes_copies" FOREIGN KEY ("copied_from_id") REFERENCES "curriculum_nodes" ("id") ON UPDATE NO ACTION ON DELETE SET NULL);
-- Create index "curriculumnode_copied_from_id" to table: "curriculum_nodes"
CREATE INDEX "curriculumnode_copied_from_id" ON "curriculum_nodes" ("copied_from_id");
-- Create index "curriculumnode_curriculum_id_kind" to table: "curriculum_nodes"
CREATE INDEX "curriculumnode_curriculum_id_kind" ON "curriculum_nodes" ("curriculum_id", "kind");
-- Create index "curriculumnode_curriculum_id_parent_id_sequence" to table: "curriculum_nodes"
CREATE INDEX "curriculumnode_curriculum_id_parent_id_sequence" ON "curriculum_nodes" ("curriculum_id", "parent_id", "sequence");
-- Create "content_placements" table
CREATE TABLE "content_placements" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), "grain" character varying NOT NULL, "page_start" bigint NULL, "page_end" bigint NULL, "origin" character varying NOT NULL DEFAULT 'manual', "confidence" double precision NULL, "status" character varying NOT NULL DEFAULT 'proposed', "confirmed_at" timestamptz NULL, "content_node_id" uuid NULL, "content_item_id" uuid NOT NULL, "copied_from_placement_id" uuid NULL, "created_by" uuid NULL, "confirmed_by" uuid NULL, "curriculum_id" uuid NOT NULL, "curriculum_node_id" uuid NULL, PRIMARY KEY ("id"), CONSTRAINT "content_placements_content_items_content_item" FOREIGN KEY ("content_item_id") REFERENCES "content_items" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "content_placements_content_nodes_placements" FOREIGN KEY ("content_node_id") REFERENCES "content_nodes" ("id") ON UPDATE NO ACTION ON DELETE RESTRICT, CONSTRAINT "content_placements_content_placements_copies" FOREIGN KEY ("copied_from_placement_id") REFERENCES "content_placements" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "content_placements_curricula_placements" FOREIGN KEY ("curriculum_id") REFERENCES "curricula" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "content_placements_curriculum_nodes_placements" FOREIGN KEY ("curriculum_node_id") REFERENCES "curriculum_nodes" ("id") ON UPDATE NO ACTION ON DELETE RESTRICT, CONSTRAINT "content_placements_persons_confirmer" FOREIGN KEY ("confirmed_by") REFERENCES "persons" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "content_placements_persons_creator" FOREIGN KEY ("created_by") REFERENCES "persons" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "content_placements_grain_node" CHECK ((((grain)::text = 'curriculum'::text) AND (curriculum_node_id IS NULL)) OR (((grain)::text = 'node'::text) AND (curriculum_node_id IS NOT NULL))));
-- Create index "contentplacement_content_item_id" to table: "content_placements"
CREATE INDEX "contentplacement_content_item_id" ON "content_placements" ("content_item_id");
-- Create index "contentplacement_content_node_id" to table: "content_placements"
CREATE INDEX "contentplacement_content_node_id" ON "content_placements" ("content_node_id");
-- Create index "contentplacement_copied_from_placement_id" to table: "content_placements"
CREATE INDEX "contentplacement_copied_from_placement_id" ON "content_placements" ("copied_from_placement_id");
-- Create index "contentplacement_curriculum_id_status" to table: "content_placements"
CREATE INDEX "contentplacement_curriculum_id_status" ON "content_placements" ("curriculum_id", "status");
-- Create index "contentplacement_curriculum_node_id_status" to table: "content_placements"
CREATE INDEX "contentplacement_curriculum_node_id_status" ON "content_placements" ("curriculum_node_id", "status");
